// Monta um item por conta social ativa + agenda publishTime em slots fixos
const clip = $('fetch-clip-do-nicho').item.json;
const rawAccounts = Array.isArray($json.publishAccounts)
  ? $json.publishAccounts
  : Array.isArray($json.data?.publishAccounts)
    ? $json.data.publishAccounts
    : Array.isArray($json.data)
      ? $json.data
      : Array.isArray($json.accounts)
        ? $json.accounts
        : [];
const activeAccounts = rawAccounts.filter(a => String(a?.status || '').toLowerCase() === 'active' || Number(a?.status) === 1);

if (activeAccounts.length === 0) {
  return [];
}

const WINDOWS = [
  { start: 7, end: 10 },
  { start: 9, end: 11 },
  { start: 12, end: 15 },
  { start: 14, end: 17 },
  { start: 18, end: 20 },
  { start: 20, end: 22 },
];
const LEAD_SECONDS = 300;

function getSpNowParts() {
  const now = new Date();
  const utcMs = now.getTime() + now.getTimezoneOffset() * 60000;
  const sp = new Date(utcMs - 3 * 60 * 60 * 1000);
  return { year: sp.getUTCFullYear(), month: sp.getUTCMonth() + 1, day: sp.getUTCDate() };
}

function spToEpoch(year, month, day, hour) {
  return Math.floor(Date.UTC(year, month - 1, day, hour + 3, 0, 0) / 1000);
}

function addDays(year, month, day, daysToAdd) {
  const d = new Date(Date.UTC(year, month - 1, day + daysToAdd));
  return { year: d.getUTCFullYear(), month: d.getUTCMonth() + 1, day: d.getUTCDate() };
}

function randInt(min, max) { return Math.floor(Math.random() * (max - min + 1)) + min; }

function getRandomSlotEpoch(nowUnix) {
  const spNow = getSpNowParts();
  for (let d = 0; d < 7; d++) {
    const dt = addDays(spNow.year, spNow.month, spNow.day, d);
    for (let i = 0; i < WINDOWS.length; i++) {
      const w = WINDOWS[i];
      const h = randInt(w.start, w.end);
      const m = randInt(0, 59);
      const epoch = spToEpoch(dt.year, dt.month, dt.day, h) + m * 60;
      if (epoch > nowUnix + LEAD_SECONDS) return epoch;
    }
  }
  const tom = addDays(spNow.year, spNow.month, spNow.day, 1);
  return spToEpoch(tom.year, tom.month, tom.day, 9) + randInt(0, 120) * 60;
}

const nowUnix = Math.floor(Date.now() / 1000);
const publishTime = getRandomSlotEpoch(nowUnix);

// Mapeia plataforma da conta Vizard para o valor aceito pelo CHECK constraint
function mapPlatform(raw) {
  const p = String(raw || '').toLowerCase().trim();
  const ALLOWED = ['youtube', 'tiktok', 'instagram', 'facebook', 'kwai'];
  if (ALLOWED.includes(p)) return p;
  if (p.includes('youtube') || p.includes('yt')) return 'youtube';
  if (p.includes('tiktok') || p.includes('tt')) return 'tiktok';
  if (p.includes('instagram') || p.includes('ig')) return 'instagram';
  if (p.includes('facebook') || p.includes('fb')) return 'facebook';
  if (p.includes('kwai')) return 'kwai';
  return p; // retorna original se nao mapeou
}

return activeAccounts.map(account => ({
  json: {
    clip_id:          clip.clip_id,
    vizard_video_id:  clip.vizard_video_id,
    titulo_final:     clip.titulo_final || '',
    descricao_final:  clip.descricao_final || '',
    descricao_base:   clip.descricao_base || '',
    hashtags:         clip.hashtags || '',
    nicho:            clip.nicho || '',
    canal_id:         clip.canal_id || '',
    score_clip:       clip.score_clip || 0,
    arquivo_clip_url: clip.arquivo_clip_url || '',
    account_id:       String(account.id || account.socialAccountId || ''),
    account_platform: mapPlatform(account.platform || account.type || account.socialPlatform || 'unknown'),
    account_name:     account.username || account.page || account.name || '',
    has_account:      true,
    publish_time:     publishTime,
  }
}));

// Avalia resultado da publicacao — SEMPRE referencia clip via fetch-clip-do-nicho
const clip = $('fetch-clip-do-nicho').item.json;
const payload = $('loop-by-account').item.json;
const result = $input.first().json;
const isSuccess = Number(result.code) === 2000;

const nowUnix = Math.floor(Date.now() / 1000);
const scheduledUnix = Number(payload.publish_time || 0);
const isScheduled = isSuccess && scheduledUnix > nowUnix + 60;

return [{
  json: {
    // IDs sempre da fonte confiavel
    clip_id:          clip.clip_id,
    vizard_video_id:  clip.vizard_video_id,
    canal_id:         clip.canal_id || '',
    nicho:            clip.nicho || '',
    // Dados da conta
    account_id:       payload.account_id,
    account_platform: payload.account_platform,
    account_name:     payload.account_name,
    publish_time:     payload.publish_time,
    // Resultado
    success:          isSuccess,
    publish_code:     result.code ?? null,
    publish_error:    isSuccess ? null : JSON.stringify(result).substring(0, 500),
    pub_status:       isSuccess ? (isScheduled ? 'agendado' : 'publicado') : 'erro',
    pub_platform_id:  isSuccess ? (result.data?.id || result.data?.videoId || null) : null,
    pub_scheduled_for: isScheduled ? scheduledUnix : null,
  }
}];

// HTTP error path — SEMPRE referencia clip via fetch-clip-do-nicho
const clip = $('fetch-clip-do-nicho').item.json;
const payload = $('loop-by-account').item.json;
const result = $input.first().json;

return [{
  json: {
    clip_id:          clip.clip_id,
    vizard_video_id:  clip.vizard_video_id,
    canal_id:         clip.canal_id || '',
    nicho:            clip.nicho || '',
    account_id:       payload.account_id,
    account_platform: payload.account_platform,
    account_name:     payload.account_name,
    publish_time:     payload.publish_time,
    success:          false,
    publish_code:     null,
    publish_error:    JSON.stringify(result).substring(0, 500),
    pub_status:       'erro',
    pub_platform_id:  null,
    pub_scheduled_for: null,
  }
}];
